let libs = [
	'data/libs/serial.js', 
	'includes/libs/hydra-synth.js', 
	'includes/libs/hy5.js'
	];

let myShader;

let matcaps = [];
let models = [];

let matcap, obj
let matcap1, obj1
let gltf

var serial;
var portName = '/dev/cu.usbmodem141301';

// Camera properties
let camera;


// Variables to store raw sensor values
var joy = {x:512, y:512};
var accel = {x:0, y:0, z:0};
var gyro  = {x:0, y:0, z:0};
var temp  = 0;

// Variables to store smoothed sensor values
var smoothedJoy = {x:512, y:512};
var smoothedGyro = {x:0, y:0, z:0};
var smoothedAccel = {x:0, y:0, z:0};

// Smoothing factor (0.0 to 1.0). Lower values are smoother.
var smoothing = 0.01;

s0.initP5() // send p5 to hydra
P5.toggle(0) // optionally hide p5

src(s0)
	.blend(src(s0).scale([1.1, 3].smooth()))
	.out()
// sandbox - end



function preload() {
	const files = [
	    { img: "radiolarian.png", obj: "radiolarian.obj" },
	    { img: "pteropod.png", obj: "pteropod.obj" },
	    { img: "dinoflagellates1.png", obj: "Dinoflagellates1.obj" },
	    { img: "dinoflagellates2.png", obj: "dinoflagellates2.obj" },
	    { img: "dinoflagellates3.png", obj: "Dinoflagellates3.obj" },
	    { img: "dinoflagellates4.png", obj: "Dinoflagellates4.obj" },
	    { img: "copepod.png", obj: "copepod.obj" }
	  ];

	  for (let i = 0; i < files.length; i++) {
	    matcaps[i] = loadImage("data/images/" + files[i].img);
	    models[i] = loadModel("data/obj/" + files[i].obj);
	  }
}

function setup() {


  createCanvas(windowWidth, windowHeight, WEBGL);
  camera = createCamera();
  pixelDensity(1)
  noStroke()
  myShader = createShader(vertShader, fragShader);

  serial = new p5.SerialPort();
  serial.open(portName);

  // When serial data arrives, call parseData
  serial.on('data', parseData);
}

const placeModel = (obj, tex, pos = {x: 0, y: 0, z: 0}) => {
	const {x,y,z} = pos;
	push()
	    myShader.setUniform("uMatcapTexture", tex)
	    // rotateX(radians(frameCount / 2))
	    // rotateZ(radians(frameCount / 4))
	    translate(x, y, z);
	    scale(10)
	    model(obj)
	pop()
}

function draw() {
  background(0)
  shader(myShader)
  updateContols();
  camera.move(map(smoothedJoy.x, 0, 1024, -5, 5), 0, map(smoothedJoy.y, 0, 1024, -5,5)*-1);
  models.forEach((obj, idx) => {
  	const tex = matcaps[idx];
  	placeModel(obj, tex, {x:0, y:0, z: idx*100})
  })



  //camera.move(0,0,10)

  //let rotX = map(smoothedAccel.x, -17000, 17000, -1000,1000);
  //let rotY = map(smoothedGyro.x, -17000, 17000, -5000, 5000);
  //let rotZ = map(smoothedAccel.y, -17000, 17000, -1000,1000);
  camera.lookAt(0, 0, 0);
}


// update controls

// Parse incoming CSV text from Arduino
function parseData() {
  let inString = serial.readLine(); // Read one line
  //console.log(inString);
  if (!inString) return;             // Ignore empty lines

  // Split by commas
  let values = inString.split(',');
  if (values.length < 9) return;    // Ensure all fields are present

  // Convert strings to numbers and update raw sensor values
  joy.x   = int(values[0]);
  joy.y   = int(values[1]);

  accel.x = int(values[2]);
  accel.y = int(values[3]);
  accel.z = int(values[4]);

  gyro.x  = int(values[5]);
  gyro.y  = int(values[6]);
  gyro.z  = int(values[7]);

  temp    = float(values[8]);
}

let updateContols = () => {

	// Smooth the sensor values using linear interpolation (lerp)
	  smoothedJoy.x = lerp(smoothedJoy.x, joy.x, smoothing);
	  smoothedJoy.y = lerp(smoothedJoy.y, joy.y, smoothing);
	  smoothedGyro.x = lerp(smoothedGyro.x, gyro.x, smoothing);
	  smoothedGyro.y = lerp(smoothedGyro.y, gyro.y, smoothing);
	  smoothedGyro.z = lerp(smoothedGyro.z, gyro.z, smoothing);
	  smoothedAccel.x = lerp(smoothedAccel.x, accel.x, smoothing);
	  smoothedAccel.y = lerp(smoothedAccel.y, accel.y, smoothing);
	  smoothedAccel.z = lerp(smoothedAccel.z, accel.z, smoothing);
	  //console.log(smoothedJoy)
};

